To insulate your core domain from vendor SDK leakage and structurally handle disparate carrier APIs (FedEx, UPS, and DHL), you should implement a **Ports and Adapters Architecture (Hexagonal Architecture)** combined with an **Anti-Corruption Layer (ACL)** and the **Strategy Pattern**.

This decouples your core business logic from third-party schemas, isolates carrier SDK dependencies inside dedicated infrastructure packages, and provides polymorphic dispatch for carrier operations.

---

## 1. Architectural Blueprint

```
                     ┌─────────────────────────────────────────────────────────┐
                     │                       CORE DOMAIN                       │
                     │                                                         │
                     │   ┌───────────────────┐       ┌─────────────────────┐   │
                     │   │   Domain Models   │       │   Carrier Service   │   │
                     │   │  (Shipment, Rate) │       │ (Business Workflow) │   │
                     │   └─────────▲─────────┘       └──────────┬──────────┘   │
                     │             │                            │              │
                     │             │               ┌────────────▼──────────┐   │
                     │             └───────────────┤   CarrierPort (Port)  │   │
                     │                             └────────────▲──────────┘   │
                     └──────────────────────────────────────────┼──────────────┘
                                                                │ Depends on Interface
   ─────────────────────────────────────────────────────────────┼─────────────────────────────────
                                                                │ Implements Interface
                     ┌──────────────────────────────────────────┴──────────────┐
                     │                  INFRASTRUCTURE ADAPTERS                │
                     │                                                         │
                     │   ┌──────────────────┐ ┌──────────────────┐ ┌─────────┴─────────┐   │
                     │   │   FedExAdapter   │ │    UPSAdapter    │ │    DHLAdapter   │   │
                     │   └────────┬─────────┘ └────────┬─────────┘ └────────┬────────┘   │
                     │            │                    │                    │            │
                     │   ┌────────▼─────────┐ ┌────────▼─────────┐ ┌────────▼────────┐   │
                     │   │   FedEx ACL      │ │    UPS ACL       │ │    DHL ACL      │   │
                     │   │ (Vendor Mappers) │ │ (Vendor Mappers) │ │ (Vendor Mappers)│   │
                     │   └────────┬─────────┘ └────────┬─────────┘ └────────┬────────┘   │
                     │            │                    │                    │            │
                     │   ┌────────▼─────────┐ ┌────────▼─────────┐ ┌────────▼────────┐   │
                     │   │  FedEx SDK/API   │ │   UPS SDK/API    │ │   DHL SDK/API   │   │
                     │   └──────────────────┘ └──────────────────┘ └─────────────────┘   │
                     └─────────────────────────────────────────────────────────────────┘
```

---

## 2. Directory Structure

```text
src/
├── domain/                            # Pure domain layer (Zero external SDK imports)
│   └── shipping/
│       ├── model/
│       │   ├── shipment.ts            # Core Shipment entity
│       │   ├── shipping-rate.ts       # Unified Rate value object
│       │   └── tracking-info.ts       # Unified Tracking info
│       ├── port/
│       │   └── carrier.port.ts        # Primary outbound port interface
│       ├── exception/
│       │   └── carrier-domain.error.ts# Domain-specific carrier exceptions
│       └── shipping.service.ts        # Business logic / Orchestration
│
└── infrastructure/                    # External carrier integrations
    └── carriers/
        ├── fedex/
        │   ├── fedex.adapter.ts       # Implements CarrierPort
        │   ├── fedex.mapper.ts        # ACL: Maps FedEx DTOs <-> Domain Entities
        │   └── fedex.client.ts        # Wrapper around FedEx SDK / HTTP client
        ├── ups/
        │   ├── ups.adapter.ts
        │   ├── ups.mapper.ts
        │   └── ups.client.ts
        ├── dhl/
        │   ├── dhl.adapter.ts
        │   ├── dhl.mapper.ts
        │   └── dhl.client.ts
        └── carrier.factory.ts          # Strategy selection & registry
```

---

## 3. Concrete Implementation

### Step 1: Define Pure Domain Models & Ports

Domain models are plain TypeScript interfaces or classes with zero references to vendor SDK types.

```typescript
// src/domain/shipping/model/shipping-rate.ts
export interface Money {
  amount: number;
  currency: string;
}

export interface RateRequest {
  originPostalCode: string;
  destinationPostalCode: string;
  weightInKg: number;
}

export interface ShippingRate {
  carrierId: 'FEDEX' | 'UPS' | 'DHL';
  serviceName: string;
  totalCost: Money;
  estimatedDeliveryDays: number;
}
```

The domain defines the outbound contract (Port) that all carriers must fulfill:

```typescript
// src/domain/shipping/port/carrier.port.ts
import { RateRequest, ShippingRate } from '../model/shipping-rate';

export interface CarrierPort {
  readonly carrierId: 'FEDEX' | 'UPS' | 'DHL';
  getRates(request: RateRequest): Promise<ShippingRate[]>;
}
```

---

### Step 2: Implement Anti-Corruption Layer (ACL) & Infrastructure Adapter

The Anti-Corruption Layer translates carrier-specific DTOs into unified domain objects. It isolates vendor type changes to a single file per carrier.

```typescript
// src/infrastructure/carriers/fedex/fedex.mapper.ts
import { RateRequest, ShippingRate } from '../../../domain/shipping/model/shipping-rate';
// Vendor SDK types imported ONLY inside infrastructure
import { FedExRateReply, FedExRateRequestPayload } from 'fedex-sdk-vendor';

export class FedExMapper {
  static toVendorRateRequest(domainReq: RateRequest): FedExRateRequestPayload {
    return {
      requestedShipment: {
        shipper: { address: { postalCode: domainReq.originPostalCode } },
        recipient: { address: { postalCode: domainReq.destinationPostalCode } },
        totalWeight: { value: domainReq.weightInKg, units: 'KG' },
      },
    };
  }

  static toDomainRates(vendorReply: FedExRateReply): ShippingRate[] {
    return vendorReply.rateReplyDetails.map((detail) => ({
      carrierId: 'FEDEX',
      serviceName: detail.serviceType,
      totalCost: {
        amount: detail.ratedShipmentDetails[0].totalNetCharge.amount,
        currency: detail.ratedShipmentDetails[0].totalNetCharge.currency,
      },
      estimatedDeliveryDays: detail.operationalDetail.transitDays ?? 3,
    }));
  }
}
```

The Adapter implements `CarrierPort` and handles network resilience and exception translation:

```typescript
// src/infrastructure/carriers/fedex/fedex.adapter.ts
import { CarrierPort } from '../../../domain/shipping/port/carrier.port';
import { RateRequest, ShippingRate } from '../../../domain/shipping/model/shipping-rate';
import { FedExMapper } from './fedex.mapper';
import { FedExClient } from './fedex.client';
import { CarrierUnavailableException } from '../../../domain/shipping/exception/carrier-domain.error';

export class FedExAdapter implements CarrierPort {
  readonly carrierId = 'FEDEX';

  constructor(private readonly client: FedExClient) {}

  async getRates(request: RateRequest): Promise<ShippingRate[]> {
    try {
      const payload = FedExMapper.toVendorRateRequest(request);
      const rawResponse = await this.client.fetchRates(payload);
      return FedExMapper.toDomainRates(rawResponse);
    } catch (error) {
      throw new CarrierUnavailableException(`FedEx API rate request failed: ${(error as Error).message}`);
    }
  }
}
```

---

### Step 3: Implement Strategy Registry for Polymorphic Dispatch

Avoid nested `switch` statements across your business logic by using a Carrier Registry to retrieve adapters dynamically.

```typescript
// src/infrastructure/carriers/carrier.factory.ts
import { CarrierPort } from '../../domain/shipping/port/carrier.port';

export class CarrierRegistry {
  private readonly adapters = new Map<'FEDEX' | 'UPS' | 'DHL', CarrierPort>();

  register(adapter: CarrierPort): void {
    this.adapters.set(adapter.carrierId, adapter);
  }

  get(carrierId: 'FEDEX' | 'UPS' | 'DHL'): CarrierPort {
    const adapter = this.adapters.get(carrierId);
    if (!adapter) {
      throw new Error(`Unregistered carrier adapter: ${carrierId}`);
    }
    return adapter;
  }

  getAll(): CarrierPort[] {
    return Array.from(this.adapters.values());
  }
}
```

---

### Step 4: Core Domain Business Service

The business logic operates purely against the `CarrierPort` abstraction:

```typescript
// src/domain/shipping/shipping.service.ts
import { RateRequest, ShippingRate } from './model/shipping-rate';
import { CarrierPort } from './port/carrier.port';

export class ShippingService {
  constructor(private readonly carriers: CarrierPort[]) {}

  async getCheapestRate(request: RateRequest): Promise<ShippingRate> {
    const results = await Promise.allSettled(
      this.carriers.map((carrier) => carrier.getRates(request))
    );

    const successfulRates = results
      .filter((res): res is PromiseFulfilledResult<ShippingRate[]> => res.status === 'fulfilled')
      .flatMap((res) => res.value);

    if (successfulRates.length === 0) {
      throw new Error('No carrier rates available');
    }

    return successfulRates.reduce((cheapest, current) =>
      current.totalCost.amount < cheapest.totalCost.amount ? current : cheapest
    );
  }
}
```

---

## 4. Tradeoff Analysis

| Metric | Direct Integration (Current State) | Ports & Adapters Architecture (Proposed) |
| :--- | :--- | :--- |
| **Domain Insulation** | Low. Vendor SDK models leak into 19 domain files. | High. Zero vendor types outside `src/infrastructure/carriers/`. |
| **Testability** | Hard. Requires mocking vendor SDKs and complex HTTP payloads. | High. Domain unit tests mock `CarrierPort` with clean fixtures. |
| **Extensibility (OCP)** | Low. Adding carrier #4 requires editing conditional logic across files. | High. Add a new `CarrierAdapter` without touching domain logic. |
| **Initial Overhead** | None (already accumulated high technical debt). | Moderate. Requires creating mappers and domain interfaces. |
| **Mapping Performance** | Zero translation overhead. | Negligible CPU cost for object transformation. |

---

## 5. Reversible Adoption Plan (Phase-by-Phase)

To execute this transition without blocking active feature work or creating massive pull requests, use a **Strangler Fig Strategy**.

```
Phase 1 (Domain Contracts) ──► Phase 2 (Adapter & ACL) ──► Phase 3 (Feature Flag Parallel Run) ──► Phase 4 (Purge SDK Leaks)
```

### Phase 1: Define Domain Ports & Entities (Non-Breaking)
1. Create `src/domain/shipping/port/carrier.port.ts` and `src/domain/shipping/model/`.
2. Do not delete existing code. Introduce canonical domain models alongside current types.

### Phase 2: Create Infrastructure Adapters & Mappers for Carrier 1
1. Build `FedExAdapter` and `FedExMapper` in `src/infrastructure/carriers/fedex/`.
2. Map current FedEx operations to the new `CarrierPort`.

### Phase 3: Route Traffic via Feature Flag (Reversible Safety Net)
1. Introduce a facade or feature flag at the call site:
```typescript
if (featureFlags.isEnabled('USE_NEW_CARRIER_PORTS')) {
  return await carrierRegistry.get('FEDEX').getRates(domainReq);
} else {
  return await legacyFedExService.getRates(legacyReq); // Instant rollback capability
}
```
2. Validate parity in staging and production.

### Phase 4: Migrate UPS, DHL & Purge Legacy SDK Bleed
1. Implement `UPSAdapter` and `DHLAdapter`.
2. Remove legacy vendor SDK imports from the 19 domain files.
3. Switch feature flag to 100% for new adapters.

### Phase 5: Enforce Boundary Governance
Add a dependency rule in `eslint-plugin-import` or `dependency-cruiser` to prevent vendor SDK imports inside `src/domain/`:

```json
// .dependency-cruiser.json excerpt
{
  "forbidden": [
    {
      "name": "domain-no-vendor-sdk",
      "severity": "error",
      "from": { "path": "^src/domain" },
      "to": { "path": "node_modules/(fedex-sdk|ups-sdk|dhl-sdk)" }
    }
  ]
}
```

To eliminate dual-write data loss and guarantee at-least-once event delivery without distributed 2PC locking, architect the system using the **Transactional Outbox Pattern** paired with an asynchronous **Relay Worker** and an **Idempotent Receiver**.

---

### Architectural Diagnosis & Force Alignment

* **The Problem (Dual-Write Anomaly)**: Writing to PostgreSQL and Kafka in a single application request path creates two independent transaction boundaries. If Kafka is unavailable or times out after PostgreSQL commits, the database transaction cannot roll back, resulting in dropped events.
* **The Solution**: Persist both the application state change (e.g., user insertion) and an outbox event record into PostgreSQL inside a **single local ACID transaction**. An independent, asynchronous background process (Outbox Relay Worker or CDC engine) reads pending outbox events and publishes them to Kafka with retry guarantees.
* **Consumer Safeguard**: Because at-least-once delivery can produce duplicate Kafka messages during network retries or worker restarts, event consumers must implement the **Idempotent Receiver Pattern** by tracking processed message identifiers.

---

### Clean Architecture Blueprint & Code Contracts

#### 1. Outbox Table Contract (`src/infrastructure/db/outbox.table.ts`)

```typescript
export interface OutboxEventRecord {
  readonly id: string;
  readonly aggregateType: string;
  readonly aggregateId: string;
  readonly eventType: string;
  readonly payload: string;
  readonly status: "PENDING" | "PUBLISHED" | "FAILED";
  readonly createdAt: Date;
  readonly publishedAt?: Date | null;
}
```

#### 2. Domain Outbox Port Contract (`src/domain/ports/outbox-repository.port.ts`)

```typescript
export interface OutboxRepositoryPort {
  insertWithinTransaction(
    dbClient: unknown,
    event: OutboxEventRecord
  ): Promise<void>;
}
```

#### 3. Atomic Application Service (`src/application/services/user-registration.service.ts`)

```typescript
export interface UserRegistrationInput {
  readonly email: string;
  readonly name: string;
}

export interface UserEntity {
  readonly id: string;
  readonly email: string;
  readonly name: string;
  readonly createdAt: Date;
}

export interface TransactionalDbClient {
  query<T>(sql: string, params: unknown[]): Promise<{ rows: T[] }>;
  begin(): Promise<void>;
  commit(): Promise<void>;
  rollback(): Promise<void>;
}

export class UserRegistrationService {
  constructor(private readonly db: TransactionalDbClient) {}

  async registerUser(input: UserRegistrationInput): Promise<UserEntity> {
    await this.db.begin();
    try {
      const userRes = await this.db.query<UserEntity>(
        "INSERT INTO users (id, email, name, created_at) VALUES ($1, $2, $3, $4) RETURNING id, email, name, created_at AS \"createdAt\"",
        [crypto.randomUUID(), input.email, input.name, new Date()]
      );
      const user = userRes.rows[0]!;

      const outboxRecord: OutboxEventRecord = {
        id: crypto.randomUUID(),
        aggregateType: "USER",
        aggregateId: user.id,
        eventType: "USER_REGISTERED",
        payload: JSON.stringify({ userId: user.id, email: user.email }),
        status: "PENDING",
        createdAt: new Date(),
      };

      await this.db.query(
        "INSERT INTO outbox_events (id, aggregate_type, aggregate_id, event_type, payload, status, created_at) VALUES ($1, $2, $3, $4, $5, $6, $7)",
        [
          outboxRecord.id,
          outboxRecord.aggregateType,
          outboxRecord.aggregateId,
          outboxRecord.eventType,
          outboxRecord.payload,
          outboxRecord.status,
          outboxRecord.createdAt,
        ]
      );

      await this.db.commit();
      return user;
    } catch (error) {
      await this.db.rollback();
      throw error;
    }
  }
}
```

#### 4. Outbox Relay Worker (`src/infrastructure/messaging/outbox-relay.worker.ts`)

```typescript
export interface KafkaPublisherPort {
  publish(topic: string, key: string, payload: string): Promise<void>;
}

export class OutboxRelayWorker {
  constructor(
    private readonly db: TransactionalDbClient,
    private readonly kafkaPublisher: KafkaPublisherPort,
    private readonly batchSize = 50
  ) {}

  async processPendingEvents(): Promise<number> {
    const res = await this.db.query<OutboxEventRecord>(
      "SELECT id, aggregate_type AS \"aggregateType\", aggregate_id AS \"aggregateId\", event_type AS \"eventType\", payload, status, created_at AS \"createdAt\" FROM outbox_events WHERE status = 'PENDING' ORDER BY created_at ASC LIMIT $1 FOR UPDATE SKIP LOCKED",
      [this.batchSize]
    );

    let processedCount = 0;
    for (const record of res.rows) {
      try {
        await this.kafkaPublisher.publish(
          `user-events.${record.eventType.toLowerCase()}`,
          record.aggregateId,
          record.payload
        );
        await this.db.query(
          "UPDATE outbox_events SET status = 'PUBLISHED', published_at = $1 WHERE id = $2",
          [new Date(), record.id]
        );
        processedCount++;
      } catch (error) {
        console.error(`Failed to publish event ${record.id} to Kafka:`, error);
        break;
      }
    }
    return processedCount;
  }
}
```

