#### 1. Domain Ports & Context Contracts (`src/domain/saga/saga-step.ts`)

```typescript
export type StepState =
  | "PENDING"
  | "EXECUTING"
  | "COMPLETED"
  | "COMPENSATING"
  | "COMPENSATED"
  | "FAILED";

export interface SagaExecutionContext<TPayload = Record<string, unknown>> {
  readonly sagaId: string;
  readonly payload: TPayload;
  readonly stepResults: Map<string, unknown>;
  readonly errors: Error[];
}

export interface SagaStep<TContext extends SagaExecutionContext = SagaExecutionContext> {
  readonly name: string;
  state: StepState;
  execute(context: TContext): Promise<void>;
  compensate(context: TContext): Promise<void>;
}
```

#### 2. Saga Orchestration Coordinator (`src/application/saga/saga-coordinator.ts`)

```typescript
import type { SagaExecutionContext, SagaStep } from "../../domain/saga/saga-step.js";

export interface SagaResult {
  readonly sagaId: string;
  readonly success: boolean;
  readonly executedSteps: readonly string[];
  readonly compensatedSteps: readonly string[];
  readonly error?: Error;
}

export class SagaCoordinator<TContext extends SagaExecutionContext> {
  private readonly steps: SagaStep<TContext>[] = [];

  registerStep(step: SagaStep<TContext>): this {
    this.steps.push(step);
    return this;
  }

  async execute(context: TContext): Promise<SagaResult> {
    const executed: SagaStep<TContext>[] = [];
    const executedNames: string[] = [];
    const compensatedNames: string[] = [];

    for (const step of this.steps) {
      step.state = "EXECUTING";
      try {
        await step.execute(context);
        step.state = "COMPLETED";
        executed.push(step);
        executedNames.push(step.name);
      } catch (err) {
        step.state = "FAILED";
        const error = err instanceof Error ? err : new Error(String(err));
        context.errors.push(error);
        await this.rollback(executed, context, compensatedNames);
        return { sagaId: context.sagaId, success: false, executedSteps: executedNames, compensatedSteps: compensatedNames, error };
      }
    }
    return { sagaId: context.sagaId, success: true, executedSteps: executedNames, compensatedSteps: compensatedNames };
  }

  private async rollback(executed: SagaStep<TContext>[], ctx: TContext, compensated: string[]): Promise<void> {
    for (let i = executed.length - 1; i >= 0; i--) {
      const step = executed[i]!;
      step.state = "COMPENSATING";
      try {
        await step.compensate(ctx);
        step.state = "COMPENSATED";
        compensated.push(step.name);
      } catch (compErr) {
        step.state = "FAILED";
        ctx.errors.push(compErr instanceof Error ? compErr : new Error(String(compErr)));
      }
    }
  }
}
```

#### 3. Platform Booking Saga Implementation (`src/application/saga/booking.saga.ts`)

```typescript
import type { SagaExecutionContext, SagaStep } from "../../domain/saga/saga-step.js";
import { SagaCoordinator } from "./saga-coordinator.js";

export interface BookingPayload {
  readonly bookingId: string;
  readonly flightId: string;
  readonly hotelId: string;
  readonly carId: string;
}

export type BookingContext = SagaExecutionContext<BookingPayload>;

export interface FlightService {
  reserve(bookingId: string, flightId: string): Promise<string>;
  cancel(ticketId: string): Promise<void>;
}

export interface HotelService {
  reserve(bookingId: string, hotelId: string): Promise<string>;
  cancel(reservationId: string): Promise<void>;
}

export class FlightBookingStep implements SagaStep<BookingContext> {
  readonly name = "FlightBookingStep";
  state: SagaStep["state"] = "PENDING";

  constructor(private readonly flightService: FlightService) {}

  async execute(ctx: BookingContext): Promise<void> {
    const ticketId = await this.flightService.reserve(ctx.payload.bookingId, ctx.payload.flightId);
    ctx.stepResults.set("flightTicketId", ticketId);
  }

  async compensate(ctx: BookingContext): Promise<void> {
    const ticketId = ctx.stepResults.get("flightTicketId") as string | undefined;
    if (ticketId) {
      await this.flightService.cancel(ticketId);
      ctx.stepResults.delete("flightTicketId");
    }
  }
}

export class HotelBookingStep implements SagaStep<BookingContext> {
  readonly name = "HotelBookingStep";
  state: SagaStep["state"] = "PENDING";

  constructor(private readonly hotelService: HotelService) {}

  async execute(ctx: BookingContext): Promise<void> {
    const reservationId = await this.hotelService.reserve(ctx.payload.bookingId, ctx.payload.hotelId);
    ctx.stepResults.set("hotelReservationId", reservationId);
  }

  async compensate(ctx: BookingContext): Promise<void> {
    const reservationId = ctx.stepResults.get("hotelReservationId") as string | undefined;
    if (reservationId) {
      await this.hotelService.cancel(reservationId);
      ctx.stepResults.delete("hotelReservationId");
    }
  }
}

export function buildBookingSaga(flight: FlightService, hotel: HotelService): SagaCoordinator<BookingContext> {
  return new SagaCoordinator<BookingContext>()
    .registerStep(new FlightBookingStep(flight))
    .registerStep(new HotelBookingStep(hotel));
}
```

