export interface ProcessedEventStore {
  hasBeenProcessed(eventId: string): Promise<boolean>;
  markProcessed(eventId: string): Promise<void>;
}

export class IdempotentConsumer {
  constructor(private readonly store: ProcessedEventStore) {}

  async consume(eventId: string, handler: () => Promise<void>): Promise<boolean> {
    if (await this.store.hasBeenProcessed(eventId)) {
      return false;
    }
    await handler();
    await this.store.markProcessed(eventId);
    return true;
  }
}
