describe("CheckoutPricingEngine", () => {
  it("calculates discounts polymorphically without modified checkout flow", () => {
    const registry = new DiscountStrategyRegistry();
    registry.register(new B2BTierDiscountStrategy());
    const engine = new CheckoutPricingEngine(registry);

    const finalPrice = engine.calculateFinalPrice({
      customerTier: "B2B_GOLD",
      couponCodes: [],
      subtotal: 100,
    });

    expect(finalPrice).toBe(85);
  });
