#### Infrastructure Adapter Example: FedEx (`src/infrastructure/carriers/adapters/fedex.adapter.ts`)
```typescript
import { CarrierPort } from '../../../domain/ports/carrier.port';
import { CarrierId, RateRequest, ShippingQuote, TrackingDetails } from '../../../domain/models/carrier.types';
import { CarrierDomainError } from '../../../domain/models/domain-errors';
// Vendor SDK imported ONLY inside the adapter layer
import * as FedExSDK from 'fedex-official-sdk'; 

export class FedExAdapter implements CarrierPort {
  public readonly carrierId: CarrierId = 'FEDEX';

  constructor(private readonly client: FedExSDK.Client) {}

  async getRates(request: RateRequest): Promise<ShippingQuote[]> {
    try {
      const fedExPayload = this.toFedExRatePayload(request);
      const response = await this.client.rateService.getRates(fedExPayload);

      return response.rateReplyDetails.map((detail) => ({
        carrierId: this.carrierId,
        serviceName: detail.serviceType,
        serviceCode: detail.serviceType,
        totalCharge: {
          amount: detail.ratedShipmentDetails[0].totalNetCharge.amount,
          currency: detail.ratedShipmentDetails[0].totalNetCharge.currency,
        },
        estimatedDelivery: new Date(detail.operationalDetail.deliveryDate),
      }));
    } catch (err) {
      throw this.normalizeError(err);
    }
  }

  async trackShipment(trackingNumber: string): Promise<TrackingDetails> {
    try {
      const response = await this.client.trackService.getByTrackingNumber({ trackingNumber });
      return {
        carrierId: this.carrierId,
        trackingNumber,
        currentStatus: this.mapStatus(response.latestStatus),
        events: response.events.map((e) => ({
          status: this.mapStatus(e.eventType),
          description: e.eventDescription,
          timestamp: new Date(e.timestamp),
          location: e.address?.city,
        })),
      };
    } catch (err) {
      throw this.normalizeError(err);
    }
  }

  supportsFeature(feature: string): boolean {
    return ['HAZMAT', 'SATURDAY_DELIVERY'].includes(feature);
  }

  private toFedExRatePayload(req: RateRequest): FedExSDK.RateRequestPayload {
    return {
      shipper: { address: { streetLines: req.origin.streetLines, city: req.origin.city, postalCode: req.origin.postalCode } },
      recipient: { address: { streetLines: req.destination.streetLines, city: req.destination.city, postalCode: req.destination.postalCode } },
      requestedPackageLineItems: req.packages.map((pkg) => ({
        weight: { value: pkg.weight, units: pkg.weightUnit },
        dimensions: { length: pkg.length, width: pkg.width, height: pkg.height, units: pkg.unit },
      })),
    };
  }

  private mapStatus(fedExStatus: string): TrackingDetails['currentStatus'] {
    switch (fedExStatus) {
      case 'DL': return 'DELIVERED';
      case 'OD': return 'OUT_FOR_DELIVERY';
      case 'PU': return 'IN_TRANSIT';
      default: return 'MANIFEST_CREATED';
    }
  }

  private normalizeError(err: unknown): CarrierDomainError {
    if (err instanceof FedExSDK.AuthError) {
      return new CarrierDomainError('FEDEX', 'AUTH_FAILED', err.message, err);
    }
    if (err instanceof FedExSDK.ValidationError) {
      return new CarrierDomainError('FEDEX', 'INVALID_ADDRESS', err.message, err);
    }
    return new CarrierDomainError('FEDEX', 'UNKNOWN', 'An unhandled FedEx error occurred', err);
  }
}
```

#### Carrier Strategy Registry (`src/infrastructure/carriers/carrier.factory.ts`)
```typescript
import { CarrierPort } from '../../domain/ports/carrier.port';
import { CarrierId } from '../../domain/models/carrier.types';

export class CarrierRegistry {
  private readonly adapters = new Map<CarrierId, CarrierPort>();

  register(adapter: CarrierPort): void {
    this.adapters.set(adapter.carrierId, adapter);
  }

  get(carrierId: CarrierId): CarrierPort {
    const adapter = this.adapters.get(carrierId);
    if (!adapter) {
      throw new Error(`Carrier adapter for '${carrierId}' is not registered.`);
    }
    return adapter;
  }
}
```

