### 1. Domain Ports Definition (Decoupling & Isolation)

Isolate all core actions behind single-responsibility domain interfaces. Each port abstracts specific subsystem operations.

```typescript
// src/domain/ports/order-ports.ts

export interface TaxCalculatorPort {
  calculateTax(order: Order): Promise<TaxDetails>;
}

export interface FraudDetectorPort {
  evaluateRisk(order: Order): Promise<FraudAssessment>;
}

export interface PaymentProcessorPort {
  authorizeAndCapture(order: Order, amount: number): Promise<PaymentResult>;
  refund(paymentId: string): Promise<void>;
}

export interface InventoryManagerPort {
  reserveItems(orderId: string, items: OrderItem[]): Promise<ReservationResult>;
  releaseItems(reservationId: string): Promise<void>;
}

export interface ShippingFulfillerPort {
  createShipment(order: Order): Promise<ShipmentManifest>;
}

export interface NotificationSenderPort {
  sendConfirmation(order: Order, manifest: ShipmentManifest): Promise<void>;
}
```

---

### 2. Concrete Pipeline Steps (LCOM4 = 1, Cyclomatic Complexity < 10)

Extract each stage of order processing into its own pipeline step. Each class handles a single responsibility, maintaining **LCOM4 = 1** and keeping cyclomatic complexity per method **under 5**.

```typescript
// src/domain/pipeline/steps/payment-step.ts
import { PaymentProcessorPort } from "../ports/order-ports.js";
import { PipelineContext, PipelineStep } from "../order-pipeline.js";

export class PaymentProcessingStep implements PipelineStep {
  constructor(private readonly paymentPort: PaymentProcessorPort) {}

  async execute(context: PipelineContext): Promise<void> {
    if (context.fraudAssessment?.isHighRisk) {
      throw new Error(`Order ${context.order.id} rejected due to high risk score.`);
    }

    const result = await this.paymentPort.authorizeAndCapture(
      context.order,
      context.taxDetails.totalAmount
    );

    if (!result.success) {
      throw new Error(`Payment failed: ${result.errorMessage}`);
    }

    context.paymentResult = result;
  }
}
```

---

### 3. Pipeline Orchestrator (Replacing Monolithic Switch/Conditionals)

The orchestrator replaces conditional branching with sequential step execution, enabling safe error recovery and rollback handling.

```typescript
// src/domain/pipeline/order-pipeline.ts

export interface PipelineContext {
  order: Order;
  taxDetails?: TaxDetails;
  fraudAssessment?: FraudAssessment;
  paymentResult?: PaymentResult;
  reservationResult?: ReservationResult;
  shipmentManifest?: ShipmentManifest;
}

export interface PipelineStep {
  execute(context: PipelineContext): Promise<void>;
}

export class OrderProcessingPipeline {
  private readonly steps: PipelineStep[] = [];

  addStep(step: PipelineStep): this {
    this.steps.push(step);
    return this;
  }

  async process(order: Order): Promise<PipelineContext> {
    const context: PipelineContext = { order };

    for (const step of this.steps) {
      await step.execute(context);
    }

    return context;
  }
}
```

---

### 4. Infrastructure Adapters (Encapsulating External SDKs)

Infrastructure adapters wrap vendor SDKs or legacy API clients to fulfill domain ports without leaking third-party details into core business rules.

```typescript
// src/infrastructure/adapters/stripe-payment.adapter.ts
import { PaymentProcessorPort } from "../../domain/ports/order-ports.js";

export class StripePaymentAdapter implements PaymentProcessorPort {
  constructor(private readonly stripeClient: StripeSDK) {}

  async authorizeAndCapture(order: Order, amount: number): Promise<PaymentResult> {
    const intent = await this.stripeClient.paymentIntents.create({
      amount: Math.round(amount * 100),
      currency: order.currency,
      confirm: true,
    });

    return {
      success: intent.status === "succeeded",
      transactionId: intent.id,
    };
  }

  async refund(paymentId: string): Promise<void> {
    await this.stripeClient.refunds.create({ payment_intent: paymentId });
  }
}
```

